commands.code:
cat > "$HOME/dev-opps-lab/k8s/gitops-app.yaml" <<YAML
apiVersion: argoproj.io/v1alpha1
kind: AppProject
metadata: {name: devopps, namespace: argocd}
spec:
  sourceRepos: ["$CONFIG_REPO"]
  destinations:
  - {server: 'https://kubernetes.default.svc', namespace: devopps}
  namespaceResourceWhitelist:
  - {group: apps, kind: Deployment}
  - {group: '', kind: Service}
---
apiVersion: argoproj.io/v1alpha1
kind: Application
metadata: {name: devopps, namespace: argocd}
spec:
  project: devopps
  source: {repoURL: "$CONFIG_REPO", targetRevision: main, path: env/devopps}
  destination: {server: 'https://kubernetes.default.svc', namespace: devopps}
YAML
kubectl apply -f "$HOME/dev-opps-lab/k8s/gitops-app.yaml"
kubectl -n argocd patch application devopps --type=merge -p '{"operation":{"sync":{}}}'
kubectl -n argocd get application devopps -w
